# Generic golden-fixture parity for the whole 515-indicator catalogue: every
# indicator is reconstructed by its constructor, fed the synthetic stream derived
# from the shared testdata/golden input (identical to gen_golden's Rust
# construction) and checked against g_<Canonical>.csv. One reflective
# runner flattens scalar, multi-output, profile and bar shapes.
#
# Like test-golden.R, the fixtures live at the repo root and are not bundled into
# the standalone package, so packaged checks (r-universe / CRAN) skip; the parity
# is enforced by the monorepo CI. Specs are generated by gen_golden_test.py.

find_golden_dir_all <- function() {
  d <- normalizePath(getwd(), winslash = "/", mustWork = FALSE)
  repeat {
    g <- file.path(d, "testdata", "golden")
    if (dir.exists(g)) return(g)
    parent <- dirname(d)
    if (identical(parent, d)) return(NULL)
    d <- parent
  }
}

golden_dir_all <- find_golden_dir_all()

# Two bounds, not one. The loose bound exists for indicators that reach a transcendental in the platform math library, whose last bit is not portable; everything else is IEEE-754 arithmetic and is bit-identical everywhere. A blanket 1e-6 is ten orders looser than the 1-ulp difference it exists for, loose enough to hide a real defect.
GOLDEN_LIBM_DEPENDENT <- local({
  if (is.null(golden_dir_all)) return(character(0))
  p <- file.path(golden_dir_all, "libm_dependent.txt")
  if (!file.exists(p)) return(character(0))
  trimws(readLines(p, warn = FALSE))
})

# Four indicators cannot be held to 1e-12 *in R specifically*, and the reason is
# the harness rather than the library. Every other binding parses the golden
# input with a correctly rounded decimal parser and reproduces the fixture bit
# for bit; R parses it with its own, and on aarch64 that differs by a last bit on
# at least one bar. These four then amplify that bit, because each one subtracts
# nearly equal quantities:
#
#   Adl                 (close - low) - (high - close), then accumulated
#   IntradayIntensity   2*close - high - low, near zero when close sits mid-bar
#   EffectiveSpread     price - mid, near zero when a trade prints at the mid
#   ChaikinOscillator   a difference of two EMAs of the same series
#
# Measured on macos-latest: 1.015e-12, 3.217e-12, 2.491e-12 and 1.000e-11. The
# streaming and batch passes report identical values for them, so the library's
# two paths agree exactly with each other -- only the comparison against a
# fixture that Rust parsed is affected. 1e-9 keeps a hundredfold margin over the
# worst observed and stays a thousand times tighter than the libm bound, so a
# real regression could not hide here.
GOLDEN_CANCELLATION_SENSITIVE <- c(
  "Adl", "ChaikinOscillator", "EffectiveSpread", "IntradayIntensity"
)

golden_tol <- function(canonical) {
  if (canonical %in% GOLDEN_LIBM_DEPENDENT) {
    1e-6
  } else if (canonical %in% GOLDEN_CANCELLATION_SENSITIVE) {
    1e-9
  } else {
    1e-12
  }
}

golden_cell <- function(s) {
  if (s == "nan") NA_real_ else if (s == "inf") Inf else if (s == "-inf") -Inf else as.numeric(s)
}

# Keeps blank lines, which is how a bar fixture records a candle that closed no
# bar; a non-bar fixture contains none.
golden_read_rows <- function(name) {
  lines <- readLines(file.path(golden_dir_all, paste0(name, ".csv")))[-1]
  lapply(lines, function(l) {
    if (nchar(l) == 0) return(numeric(0))
    vapply(strsplit(l, ",", fixed = TRUE)[[1]], golden_cell, numeric(1), USE.NAMES = FALSE)
  })
}

golden_input_rows <- function() {
  lapply(
    readLines(file.path(golden_dir_all, "input.csv"))[-1],
    function(l) as.numeric(strsplit(l, ",", fixed = TRUE)[[1]])
  )
}

# The reflective runner below is shared by the value pass and the lifecycle
# pass, so the two cannot end up feeding the indicators different streams.
deriv_fields <- function(r) {
  o <- r[1]; h <- r[2]; l <- r[3]; c <- r[4]; v <- r[5]
  c((c - o) / c * 0.01, c, c - 0.5, c + 1.0, v * 10, v * 0.6, v * 0.4,
    v * 0.55, v * 0.45, h - c, c - l)
}
cross_lists <- function(r) {
  o <- r[1]; c <- r[4]; v <- r[5]; j <- 0:4
  list(change = (c - o) + j, volume = v + j * 10,
       newHigh = as.numeric(j %% 2 == 0), newLow = as.numeric(j %% 3 == 0),
       aboveMa = as.numeric(j %% 2 == 0), onBuy = as.numeric(j %% 3 == 0))
}
ob_lists <- function(r) {
  c <- r[4]; v <- r[5]; k <- 1:5
  list(bp = c - 0.1 * k, bs = v / k, ap = c + 0.1 * k, asz = v * 0.9 / k)
}
flatten <- function(o, arch, width) {
  if (arch %in% c("profile_bins")) {
    if (is.null(o) || length(o) == 0 || all(is.na(o))) return(rep(NA_real_, width))
    return(as.numeric(o))
  }
  if (arch == "profile_pricebins") {
    if (is.list(o)) return(c(o$price_low, o$price_high, as.numeric(o$values)))
    return(rep(NA_real_, width))
  }
  if (arch %in% c("bars_close", "bars_candle4", "bars_candle5", "footprint")) {
    if (is.null(o) || length(o) == 0) return(numeric(0))
    if (is.matrix(o)) return(as.numeric(t(o)))
    return(as.numeric(o))
  }
  as.numeric(o)
}

golden_compute <- function(spec, ind, r, i) {
  o <- r[1]; h <- r[2]; l <- r[3]; cl <- r[4]; v <- r[5]; ts <- as.integer(i - 1)
  out <- switch(spec$arch,
    scalar_f64 = update(ind, cl),
    multi_f64  = update(ind, cl),
    pairwise = , multi_pairwise = update(ind, cl, o),
    scalar_candle = , multi_candle = , profile_bins = , profile_pricebins =
      update(ind, o, h, l, cl, v, ts),
    trade = update(ind, cl, v, cl >= o, ts),
    trademid = update(ind, cl, v, cl >= o, ts, (h + l) / 2),
    ob = { L <- ob_lists(r); update(ind, L$bp, L$bs, L$ap, L$asz) },
    cross = { L <- cross_lists(r)
      update(ind, L$change, L$volume, L$newHigh, L$newLow, L$aboveMa, L$onBuy, ts) },
    deriv = , deriv_multi = { d <- deriv_fields(r)
      do.call(update, c(list(ind), as.list(d), list(ts))) },
    bars_close = update(ind, cl, cl, cl, cl, 1, 0L),
    bars_candle4 = update(ind, o, h, l, cl, 1, 0L),
    bars_candle5 = update(ind, o, h, l, cl, v, 0L),
    footprint = update(ind, cl, v, cl >= o, ts),
    stop("arch ", spec$arch)
  )
  flatten(out, spec$arch, spec$width)
}

# Drive one indicator over the whole golden input, rows flattened as the fixture
# stores them.
golden_drive <- function(spec, ind, input_rows) {
  lapply(seq_along(input_rows), function(i) golden_compute(spec, ind, input_rows[[i]], i))
}

# A result as one flat, row-major numeric vector, whatever shape it came back in.
golden_flatten <- function(x) {
  if (is.matrix(x)) as.numeric(t(x)) else as.numeric(x)
}

# One expectation for a whole indicator rather than one per value. testthat
# records every expectation, and at 515 indicators x 80 rows x up to 52 columns
# that bookkeeping costs far more than the arithmetic. A mismatch still fails;
# the message says how many values differ and names the first.
golden_expect_values <- function(canon, got, want, tol) {
  if (length(got) != length(want)) {
    expect_equal(length(got), length(want),
      info = sprintf("%s: batch produced %d values, fixture has %d",
                     canon, length(got), length(want)))
    return(invisible(NULL))
  }
  ok <- (is.na(want) & is.na(got)) |
    (is.infinite(want) & is.infinite(got) & sign(want) == sign(got)) |
    (is.finite(want) & is.finite(got) & abs(got - want) <= tol * pmax(1, abs(want)))
  bad <- which(!ok)
  # Full precision, and the relative delta: a last-bit divergence prints
  # identically at R's default seven digits, which says nothing about whether it
  # is a rounding difference or a real one.
  expect_equal(length(bad), 0L,
    info = if (length(bad) == 0L) canon else sprintf(
      "%s: %d of %d values differ; first at %d (got %s want %s, rel %.3e)",
      canon, length(bad), length(want), bad[1],
      format(got[bad[1]], digits = 17), format(want[bad[1]], digits = 17),
      abs(got[bad[1]] - want[bad[1]]) / max(1, abs(want[bad[1]]))))
}

# Whether the reference fixture holds a single finite value. A few indicators
# never emit over this input, and for those "ready once the series is done"
# would be the wrong assertion. Reading it off the fixture beats inferring it at
# runtime from a row that might legitimately be NA.
golden_fixture_emits <- function(canon) {
  any(vapply(golden_read_rows(paste0("g_", canon)), function(r) any(is.finite(r)), logical(1)))
}

test_that("all 515 indicators match the Rust golden fixtures", {
  skip_if(is.null(golden_dir_all), "golden fixtures not bundled with the package")
  source(test_path("golden_specs.R"), local = TRUE)
  read_rows <- golden_read_rows
  compute <- golden_compute
  input_rows <- golden_input_rows()

  for (spec in GOLDEN_SPECS) {
    ind <- do.call(get(spec$canon), as.list(spec$params))
    expect_identical(name(ind), spec$name,
      info = sprintf("%s name()", spec$canon))
    exp <- read_rows(paste0("g_", spec$canon))
    for (i in seq_along(input_rows)) {
      got <- compute(spec, ind, input_rows[[i]], i)
      want <- exp[[i]]
      expect_equal(length(got), length(want),
        info = sprintf("%s row %d arity", spec$canon, i))
      for (k in seq_along(want)) {
        w <- want[k]; g <- got[k]
        if (is.na(w)) {
          expect_true(is.na(g), info = sprintf("%s row %d col %d: want NA", spec$canon, i, k))
        } else if (is.infinite(w)) {
          expect_true(is.infinite(g) && sign(g) == sign(w),
            info = sprintf("%s row %d col %d: want %g", spec$canon, i, k, w))
        } else {
          expect_lte(abs(g - w), golden_tol(spec$canon) * max(1, abs(w)),
            label = sprintf("%s row %d col %d (got %s want %g)", spec$canon, i, k, as.character(g), w))
        }
      }
    }
  }
})

# The contract around the values. The pass above checks only what an indicator
# computes, so a reset that forgot a field, or an is_ready wired to a value that
# happens to move at the right time, replays perfectly clean through it.
test_that("all 515 indicators honour reset, is_ready and warmup_period", {
  skip_if(is.null(golden_dir_all), "golden fixtures not bundled with the package")
  source(test_path("golden_specs.R"), local = TRUE)
  input_rows <- golden_input_rows()

  for (spec in GOLDEN_SPECS) {
    ind <- do.call(get(spec$canon), as.list(spec$params))
    # The ten bar builders have no warmup or ready state: one candle can
    # complete any number of bars, so there is nothing for them to be ready for.
    stateful <- !startsWith(spec$arch, "bars_")
    if (stateful) {
      expect_false(is_ready(ind), info = sprintf("%s: ready before any input", spec$canon))
      expect_gte(warmup_period(ind), 1L, label = sprintf("%s warmup_period", spec$canon))
    }
    first <- golden_drive(spec, ind, input_rows)
    if (stateful && golden_fixture_emits(spec$canon)) {
      expect_true(is_ready(ind),
        info = sprintf("%s: not ready after the whole series, but the fixture has values", spec$canon))
    }
    reset(ind)
    if (stateful) {
      expect_false(is_ready(ind), info = sprintf("%s: still ready after reset", spec$canon))
    }
    # Equality, not tolerance: the same code over the same input in the same
    # session has no reason to differ in a single bit, and a tolerance here
    # would hide exactly the leftover state this is looking for.
    second <- golden_drive(spec, ind, input_rows)
    for (i in seq_along(first)) {
      before <- first[[i]]
      after <- second[[i]]
      expect_equal(length(after), length(before),
        info = sprintf("%s row %d: arity changed after reset", spec$canon, i))
      differing <- which(!((is.na(before) & is.na(after)) | (!is.na(before) & !is.na(after) & before == after)))
      expect_length(differing, 0L)
    }
  }
})

# The whole-series columns for one archetype, in the order its batch declares
# them, named where the argument is a per-bar width rather than a column.
# Logicals cross the C boundary as 0/1 doubles.
#
# A cross-section or order-book snapshot is one flat column per field, bar `i`
# at `[i*width, (i+1)*width)`, which is the shape the Java and C# batches take
# too. `golden_flat` builds one from the same per-bar values `compute` feeds
# `update`.
golden_flat <- function(input_rows, f) {
  # `vapply` returns a width x n matrix, one column per bar, and R stores it
  # column-major -- so reading it straight out is already bar-major. Transposing
  # first would interleave the bars, which is the layout the native routine does
  # not take.
  as.numeric(vapply(input_rows, f, numeric(5)))
}

golden_batch_columns <- function(arch, input_rows) {
  n <- length(input_rows)
  col <- function(k) vapply(input_rows, function(r) r[k], numeric(1))
  open <- col(1); high <- col(2); low <- col(3); close <- col(4); volume <- col(5)
  ts <- as.numeric(seq_len(n) - 1)
  switch(arch,
    scalar_f64 = , multi_f64 = list(close),
    pairwise = , multi_pairwise = list(close, open),
    scalar_candle = , multi_candle = , profile_bins = , profile_pricebins =
      list(open, high, low, close, volume, ts),
    trade = , footprint = list(close, volume, as.numeric(close >= open), ts),
    trademid = list(close, volume, as.numeric(close >= open), ts, (high + low) / 2),
    deriv = , deriv_multi = c(
      lapply(seq_len(11), function(f) vapply(input_rows, function(r) deriv_fields(r)[f], numeric(1))),
      list(ts)
    ),
    cross = list(
      golden_flat(input_rows, function(r) (r[4] - r[1]) + 0:4),
      golden_flat(input_rows, function(r) r[5] + (0:4) * 10),
      golden_flat(input_rows, function(r) as.numeric((0:4) %% 2 == 0)),
      golden_flat(input_rows, function(r) as.numeric((0:4) %% 3 == 0)),
      golden_flat(input_rows, function(r) as.numeric((0:4) %% 2 == 0)),
      golden_flat(input_rows, function(r) as.numeric((0:4) %% 3 == 0)),
      members = 5L, ts
    ),
    ob = list(
      golden_flat(input_rows, function(r) r[4] - 0.1 * (1:5)),
      golden_flat(input_rows, function(r) r[5] / (1:5)),
      n_bids = 5L,
      golden_flat(input_rows, function(r) r[4] + 0.1 * (1:5)),
      golden_flat(input_rows, function(r) r[5] * 0.9 / (1:5)),
      n_asks = 5L
    ),
    bars_close = list(close, close, close, close, rep(1, n), rep(0, n)),
    bars_candle4 = list(open, high, low, close, rep(1, n), rep(0, n)),
    bars_candle5 = list(open, high, low, close, volume, rep(0, n)),
    stop("batch arch ", arch)
  )
}

# A batch is a separate native path from `update`; until this existed only a
# handful of indicators had ever been checked through it, and 39 of them had no
# batch to check.
test_that("all 515 indicators match the Rust golden fixtures through batch", {
  skip_if(is.null(golden_dir_all), "golden fixtures not bundled with the package")
  source(test_path("golden_specs.R"), local = TRUE)
  input_rows <- golden_input_rows()
  n <- length(input_rows)

  checked <- 0L
  for (spec in GOLDEN_SPECS) {
    checked <- checked + 1L
    ind <- do.call(get(spec$canon), as.list(spec$params))
    got <- do.call(batch, c(list(ind), golden_batch_columns(spec$arch, input_rows)))
    exp <- golden_read_rows(paste0("g_", spec$canon))

    want <- if (identical(spec$arch, "footprint")) {
      # Footprint reports the whole book after each trade, so the batch holds
      # the final snapshot rather than every intermediate one.
      nonempty <- Filter(function(r) length(r) > 0, exp)
      if (length(nonempty)) nonempty[[length(nonempty)]] else numeric(0)
    } else {
      # A bar builder completes an unpredictable number of bars per candle, so
      # its batch is the concatenation of what streaming emits row by row; for
      # everything else the fixture is one row per input and flattens the same.
      unlist(exp, use.names = FALSE)
    }
    golden_expect_values(spec$canon, golden_flatten(got), want, golden_tol(spec$canon))
  }
  # Every indicator has a batch now; the cross-section, order-book, profile and
  # bar-builder families had none until the R shims were generated for them.
  expect_equal(checked, 515L)
})
